ALTER TABLE "order_stage_events" ADD CONSTRAINT "order_stage_events_stage_chk" CHECK ("stage" IN ('checkout_started','checkout_validated','checkout_refused','order_placed','charge_quoted','pricing_applied','stock_reserved','reservation_failed','stock_issued','stock_released','stock_returned','approval_requested','approval_approved','approval_rejected','approval_escalated','approval_reopened','approval_withdrawn','payment_started','prompt_sent','payment_pending_verification','payment_confirmed','payment_partial','payment_reversed','payment_failed','payment_expired','payment_retried','payment_reconciled','payment_discrepancy','refund_requested','refund_completed','refund_failed','released_for_fulfilment','blocked','unblocked','pick_started','picked','packed','ready','dispatched','out_for_delivery','delivery_attempted','delivered','part_delivered','delivery_failed','returned_to_stock','collected','invoice_issued','kra_submitted','kra_signed','kra_failed','delivery_invoice_signed','delivery_invoice_failed','delivery_invoice_skipped','credit_note_issued','completed','cancelled','failed','refunded','status_corrected','unrecorded_change'));
